import random


def print_board(board):
    for i, row in enumerate(board):
        print(" " + " | ".join(row))
        if i < 2:
            print("---+---+---")


def check_winner(board, player):
    for i in range(3):
        if all(board[i][j] == player for j in range(3)):
            return True
        if all(board[j][i] == player for j in range(3)):
            return True
    if all(board[i][i] == player for i in range(3)):
        return True
    if all(board[i][2 - i] == player for i in range(3)):
        return True
    return False


def get_empty_cells(board):
    return [(i, j) for i in range(3) for j in range(3) if board[i][j] == " "]


def computer_move(board):
    empty = get_empty_cells(board)
    # Try to win
    for r, c in empty:
        board[r][c] = "O"
        if check_winner(board, "O"):
            return
        board[r][c] = " "
    # Block player from winning
    for r, c in empty:
        board[r][c] = "X"
        if check_winner(board, "X"):
            board[r][c] = "O"
            return
        board[r][c] = " "
    # Pick a random cell
    r, c = random.choice(empty)
    board[r][c] = "O"


def main():
    board = [[" "] * 3 for _ in range(3)]
    print("Tic-Tac-Toe: You are X, computer is O.")
    print("Enter row and column (0-2) separated by a space.\n")
    print_board(board)

    while True:
        # Player turn
        while True:
            try:
                r, c = map(int, input("\nYour move (row col): ").split())
                if 0 <= r <= 2 and 0 <= c <= 2 and board[r][c] == " ":
                    break
                print("Invalid move. Try again.")
            except (ValueError, EOFError):
                print("Enter two numbers 0-2 separated by a space.")

        board[r][c] = "X"
        print_board(board)

        if check_winner(board, "X"):
            print("\nYou win!")
            return
        if not get_empty_cells(board):
            print("\nIt's a draw!")
            return

        # Computer turn
        computer_move(board)
        print("\nComputer plays:")
        print_board(board)

        if check_winner(board, "O"):
            print("\nComputer wins!")
            return
        if not get_empty_cells(board):
            print("\nIt's a draw!")
            return


if __name__ == "__main__":
    main()
